/** URLs of the catalog API endpoints. */

import { QueryError, encodeComponent } from "./encode.ts";
import type { QueryParams, QueryValue } from "./types.ts";
import { withQuery } from "./url.ts";

/** The catalog API endpoints and their paths; ":name" segments are path parameters. */
export const ENDPOINTS = {
  search: "/v2/search",
  product: "/v2/products/:id",
  reviews: "/v2/products/:id/reviews",
  category: "/v2/categories/:slug/products",
} as const;

/** The name of a catalog API endpoint. */
export type EndpointName = keyof typeof ENDPOINTS;

/**
 * The URL of a catalog API endpoint: ``base`` (a trailing slash is dropped), the
 * endpoint's path with its path parameters filled in from ``params`` and
 * percent-encoded, and the other parameters as the query string. Throws a QueryError
 * when a path parameter is missing or is not a single value.
 */
export function endpointUrl(base: string, name: EndpointName, params: QueryParams = {}): string {
  const rest: Record<string, QueryValue> = { ...params };
  const path = ENDPOINTS[name].replace(/:([a-z]+)/g, (_match, key: string) => {
    const value = params[key];
    if (value === null || value === undefined || Array.isArray(value)) {
      throw new QueryError(`endpoint ${name} needs a single value for its ${key} parameter`);
    }
    delete rest[key];
    return encodeComponent(String(value));
  });
  return withQuery(`${base.replace(/\/+$/, "")}${path}`, rest);
}

/** Adding query parameters to URLs. */

import type { StringifyOptions } from "./stringify.ts";
import { stringify } from "./stringify.ts";
import type { QueryParams } from "./types.ts";

/**
 * ``url`` with ``params`` added to its query string: after any query the URL already
 * has and before its #fragment. The URL is returned unchanged when ``params`` write
 * nothing.
 */
export function withQuery(
  url: string,
  params: QueryParams,
  options: StringifyOptions = {},
): string {
  const query = stringify(params, options);
  if (query === "") {
    return url;
  }
  const hash = url.indexOf("#");
  const base = hash === -1 ? url : url.slice(0, hash);
  const fragment = hash === -1 ? "" : url.slice(hash);
  let separator = "?";
  if (base.includes("?")) {
    separator = base.endsWith("?") || base.endsWith("&") ? "" : "&";
  }
  return `${base}${separator}${query}${fragment}`;
}

/** Reading query strings back into objects. */

import { decodeComponent } from "./encode.ts";
import type { ParsedQuery } from "./types.ts";

/** Add one value under ``key``; a key seen before collects its values in an array. */
function add(result: ParsedQuery, key: string, value: string): void {
  if (!Object.hasOwn(result, key)) {
    // defineProperty, so that a key such as "__proto__" stays an ordinary key.
    Object.defineProperty(result, key, {
      value,
      enumerable: true,
      writable: true,
      configurable: true,
    });
    return;
  }
  const existing = result[key];
  result[key] = Array.isArray(existing) ? [...existing, value] : [existing, value];
}

/**
 * Parse a query string, with or without a leading "?". A key that appears once maps
 * to its value, a repeated key to an array of its values in order, and a key without
 * "=" to "". Empty pairs ("a=1&&b=2") are skipped. Both "+" and "%20" read as a space.
 * Throws a QueryError for a malformed percent escape.
 */
export function parse(query: string): ParsedQuery {
  const text = query.startsWith("?") ? query.slice(1) : query;
  const result: ParsedQuery = {};
  for (const pair of text.split("&")) {
    if (pair === "") {
      continue;
    }
    const equals = pair.indexOf("=");
    const key = decodeComponent(equals === -1 ? pair : pair.slice(0, equals));
    const value = equals === -1 ? "" : decodeComponent(pair.slice(equals + 1));
    add(result, key, value);
  }
  return result;
}

/** Percent-encoding and decoding of query string components. */

/** Text that cannot be encoded, or a query string that cannot be read. */
export class QueryError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "QueryError";
  }
}

/** Characters that encodeURIComponent leaves alone but the catalog API wants encoded. */
const EXTRA = /[!'()*]/g;

/**
 * Percent-encode text for a query string or a path segment: every UTF-8 byte as %XX
 * with upper-case hex digits, except letters, digits, and - . _ ~. Throws a QueryError
 * for text with a lone surrogate, which has no UTF-8 form.
 */
export function encodeComponent(text: string): string {
  let encoded: string;
  try {
    encoded = encodeURIComponent(text);
  } catch {
    throw new QueryError(`cannot encode ${JSON.stringify(text)}: it is not valid Unicode text`);
  }
  return encoded.replace(EXTRA, (char) => `%${char.charCodeAt(0).toString(16).toUpperCase()}`);
}

/**
 * Decode one component of a query string: %XX escapes, and + as a space (HTML forms
 * write a space as +). Throws a QueryError for a malformed escape.
 */
export function decodeComponent(text: string): string {
  try {
    return decodeURIComponent(text.replace(/\+/g, " "));
  } catch {
    throw new QueryError(`malformed percent escape in ${JSON.stringify(text)}`);
  }
}

